int linear_search(int a[], int n, int x)
{
    int currentIndex = 0;
    int foundFlag = 0;
    int totalValueSoFar = -1;

    while (currentIndex <= n)
    {
        if (a[currentIndex] == x)
        {
            foundFlag = 1;
            totalValueSoFar = currentIndex;
        }
        else
        {
            foundFlag = foundFlag;
        }

        currentIndex = currentIndex + 1;
    }

    if (foundFlag == 1)
    {
        return totalValueSoFar;
    }
    else
    {
        return -1;
    }
}
